const event = input.event || {};
if (event.type === 'preview' || event.type === 'render') { return {state: input.state}; }
const s = Object.assign({}, input.state);
if (event.type === 'action') {
  const id = String(event.actionId || '');
  if (id === 'restart') {
    s.score = 0;
    s.won = false;
    s.enabled = true;
    s.o2 = false; s.o5 = false; s.o8 = false;
    s.s2 = ''; s.s5 = ''; s.s8 = '';
    s.message = 'Игра началась заново. Найдите три звезды.';
    return {state: s};
  }
  const m = /^cell([1-9])$/.exec(id);
  if (m) {
    if (s.won) {
      s.message = 'Победа! Все три звезды найдены. Поле закрыто, нажмите «Заново».';
      return {state: s};
    }
    const n = Number(m[1]);
    if (n === 2 || n === 5 || n === 8) {
      const k = 'o' + n;
      if (s[k] === true) {
        s.message = 'Эта звезда уже открыта. Очко начислено один раз.';
      } else {
        s[k] = true;
        s.score = s.score + 1;
        s['s' + n] = '★';
        s.message = 'Звезда! Начислено одно очко.';
      }
    } else {
      s.message = 'Пустая клетка. Очков нет.';
    }
    if (s.score >= 3) {
      s.won = true;
      s.enabled = false;
      s.message = 'Победа! Все три звезды найдены.';
    }
  }
}
return {state: s};
